  OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

  // traverse the component until we find a node that satisfies the predicate
  while (circulator.hasNext()) {
    Node currentNode = circulator.next();
    if (predicate.test(currentNode)) {
      return circulator;
    }
  }

  // if we reach this point, we haven't found a node that satisfies the predicate, so return a circulator to the stop node
  return circulator;
