@Override
protected V provideNextVertex() {
    // Step 1: Check if there are still unvisited vertices in the queue
    if (unvisitedVertices.isEmpty()) {
        // If not, throw an exception
        throw new IllegalStateException("There are no more unvisited vertices in the graph");
    }

    // Step 2: Get the next vertex from the queue
    V nextVertex = unvisitedVertices.poll();

    // Step 3: Mark the vertex as visited and add the vertex to the visited stack
    visitedVertices.push(nextVertex);

    // Step 4: Add the vertex's neighbors to the queue if they have not been visited before
    for (V neighbor : graph.getNeighbors(nextVertex)) {
        if (!visitedVertices.contains(neighbor)) {
            unvisitedVertices.add(neighbor);
        }
    }

    // Step 5: Return the next vertex
    return nextVertex;
}

