private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
  if (graph == null || vertices == null || vertices.isEmpty()) {
    return false;
  }

  Set<V> remainingVertices = new HashSet<>(vertices);
  while (!remainingVertices.isEmpty()) {
    V vertex = remainingVertices.iterator().next();
    remainingVertices.remove(vertex);
    for (V otherVertex : remainingVertices) {
      if (!graph.hasEdgeBetween(vertex, otherVertex)) {
        return false;
      }
    }
  }

  return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // step 1: check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    // step 2: check if the input vertices is null or empty
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Vertices cannot be null or empty");
    }
    // step 3: check if the input vertices contains duplicate elements
    if (vertices.size() != vertices.stream().distinct().count()) {
        throw new IllegalArgumentException("Vertices cannot contain duplicate elements");
    }
    // step 4: check if the input graph contains the given vertices
    if (!graph.containsAllVertices(vertices)) {
        throw new IllegalArgumentException("Graph does not contain all the given vertices");
    }
    // step 5: check if the induced subgraph is complete
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.adjacentVertices(v1).contains(v2)) {
                return false;
            }
        }
    }
    return true;
}

