public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart >= buf.length()) {
        throw new IndexOutOfBoundsException("nameStart must be less than the length of the buffer");
    }
    if (buf.charAt(nameStart) == ' ') {
        throw new IllegalArgumentException("nameStart must not point to a space character");
    }
    String name = buf.substring(nameStart);
    String[] words = name.split("(?=\\p{Lu})|(?<=\\p{L})");
    for (String word : words) {
        if (!word.isEmpty()) {
            buf.append(word.charAt(0));
        }
    }
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        throw new NullPointerException("buf must not be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds: " + nameStart);
    }
    int nameEnd = buf.length();
    if (nameEnd - nameStart < 2) {
        throw new IllegalArgumentException("name length must be at least 2 characters: " + (nameEnd - nameStart));
    }
    char firstChar = buf.charAt(nameStart);
    if (Character.isLowerCase(firstChar)) {
        throw new IllegalArgumentException("name must start with an uppercase letter: " + firstChar);
    }
    char secondChar = buf.charAt(nameStart + 1);
    if (Character.isLowerCase(secondChar)) {
        throw new IllegalArgumentException("name must start with an uppercase letter: " + secondChar);
    }
    buf.setCharAt(nameStart, Character.toUpperCase(firstChar));
    buf.setCharAt(nameStart + 1, Character.toUpperCase(secondChar));
}

