public List<TimeRange> buildTimeRanges(long start, long end) {

    // Check if the input time range is valid
    if (start > end) {
        throw new IllegalArgumentException("Start time must be before end time");
    }

    // Initialize the list of time ranges
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the total time range
    long totalTimeRange = end - start;

    // Split the time range into chunks that are smaller than the maximum fetch data duration
    long chunkSize = FETCH_DATA_DURATION;
    for (long i = 0; i < totalTimeRange; i += chunkSize) {
        long chunkStart = start + i;
        long chunkEnd = Math.min(chunkStart + chunkSize - 1, end);
        timeRanges.add(new TimeRange(chunkStart, chunkEnd));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start > end) {
        throw new IllegalArgumentException("Invalid time range: start time must be less than or equal to end time");
    }
    if (end - start > FETCH_DATA_DURATION) {
        long splitStart = start;
        long splitEnd = start + FETCH_DATA_DURATION;
        while (splitEnd < end) {
            timeRanges.add(new TimeRange(splitStart, splitEnd));
            splitStart = splitEnd + 1;
            splitEnd = Math.min(splitStart + FETCH_DATA_DURATION, end);
        }
    } else {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    // Split the time range into smaller ranges if the duration is too long
    while (start < end) {
        long splitStart = start;
        long splitEnd = Math.min(start + duration, end);
        timeRanges.add(new TimeRange(splitStart, splitEnd));
        start += duration;
    }

    return timeRanges;
}

