public Mappings diffStructure(String tableName, Mappings mappings) {
    // Check for null inputs
    Objects.requireNonNull(tableName, "tableName should not be null");
    Objects.requireNonNull(mappings, "mappings should not be null");

    // Get the current index mappings
    Mappings currentMappings = MappingUtils.getMappingsFromIndex(tableName);

    // Create a new mapping to store the difference
    Mappings diffMappings = new Mappings();

    // Iterate over the current mappings and check for differences
    for (Map.Entry<String, Mapping> currentMapping : currentMappings.mappings().entrySet()) {
        String fieldName = currentMapping.getKey();
        Mapping currentFieldMapping = currentMapping.getValue();

        // Check if the field exists in the provided mappings
        if (!mappings.mappings().containsKey(fieldName)) {
            // Field does not exist in the provided mappings, add it to the difference mappings
            diffMappings.addMapping(fieldName, currentFieldMapping);
        } else {
            // Field exists in both mappings, check for differences
            Mapping providedFieldMapping = mappings.mappings().get(fieldName);
            if (!currentFieldMapping.equals(providedFieldMapping)) {
                // Field mappings are different, add it to the difference mappings
                diffMappings.addMapping(fieldName, currentFieldMapping);
            }
        }
    }

    // Return the difference mappings
    return diffMappings;
}

